import Foundation

// MARK: - ApprovalAnswer
public struct ApprovalAnswer: Codable, Sendable {
    public let answerToken: String
    public let approvalID: String
    public let decision: DecisionEnum
    public let scope: GrantScope?

    public enum CodingKeys: String, CodingKey {
        case answerToken = "answerToken"
        case approvalID = "approvalId"
        case decision = "decision"
        case scope = "scope"
    }

    public init(answerToken: String, approvalID: String, decision: DecisionEnum, scope: GrantScope?) {
        self.answerToken = answerToken
        self.approvalID = approvalID
        self.decision = decision
        self.scope = scope
    }
}

public enum DecisionEnum: String, Codable, Sendable {
    case approve = "approve"
    case deny = "deny"
}

public enum GrantScope: String, Codable, Sendable {
    case always = "always"
    case once = "once"
    case session = "session"
    case site = "site"
    case task = "task"
}

// MARK: - ApprovalBlock
public struct ApprovalBlock: Codable, Sendable {
    public let approvalID: String
    public let type: ApprovalBlockType

    public enum CodingKeys: String, CodingKey {
        case approvalID = "approvalId"
        case type = "type"
    }

    public init(approvalID: String, type: ApprovalBlockType) {
        self.approvalID = approvalID
        self.type = type
    }
}

public enum ApprovalBlockType: String, Codable, Sendable {
    case approval = "approval"
}

// MARK: - ApprovalCreatedPayload
public struct ApprovalCreatedPayload: Codable, Sendable {
    /// This connection's surface token, if any
    public let answerToken: String?
    public let approval: ApprovalRequest

    public enum CodingKeys: String, CodingKey {
        case answerToken = "answerToken"
        case approval = "approval"
    }

    public init(answerToken: String?, approval: ApprovalRequest) {
        self.answerToken = answerToken
        self.approval = approval
    }
}

// MARK: - ApprovalRequest
public struct ApprovalRequest: Codable, Sendable {
    public let bindingHash: String
    public let decidedAt: String?
    public let decidedBy: DecidedByClass?
    public let details: [String: JSONAny]
    public let deviceOnly: Bool
    public let expiresAt: String
    public let grantID: String?
    public let grantKey: String
    public let id: String
    public let invalidatedReason: String?
    public let kind: ApprovalKind
    public let requestedAt: String
    public let requestedBy: RequestedBy
    public let requiresAuthentication: Bool
    public let scopeGranted: GrantScope?
    public let scopesOffered: [GrantScope]
    public let sideEffect: SideEffect?
    public let status: ApprovalStatus
    public let summary: String
    public let surfaces: [String]
    public let taint: Bool
    public let target: Target?
    public let targetKind: TargetKind?

    public enum CodingKeys: String, CodingKey {
        case bindingHash = "bindingHash"
        case decidedAt = "decidedAt"
        case decidedBy = "decidedBy"
        case details = "details"
        case deviceOnly = "deviceOnly"
        case expiresAt = "expiresAt"
        case grantID = "grantId"
        case grantKey = "grantKey"
        case id = "id"
        case invalidatedReason = "invalidatedReason"
        case kind = "kind"
        case requestedAt = "requestedAt"
        case requestedBy = "requestedBy"
        case requiresAuthentication = "requiresAuthentication"
        case scopeGranted = "scopeGranted"
        case scopesOffered = "scopesOffered"
        case sideEffect = "sideEffect"
