// MARK: - Receipt
public struct Receipt: Codable, Sendable {
    public let approvalID: String?
    public let createdAt: String
    public let externalRefs: [String: ExternalRef]
    public let id: String
    /// ApprovalKind vocabulary plus read kinds
    public let kind: String
    public let outcome: ReceiptOutcome
    public let payload: [String: JSONAny]?
    /// Client-visible short id for the receipt line
    public let shortID: String?
    public let summary: String
    public let taskID: String?
    public let toolCallID: String?

    public enum CodingKeys: String, CodingKey {
        case approvalID = "approvalId"
        case createdAt = "createdAt"
        case externalRefs = "externalRefs"
        case id = "id"
        case kind = "kind"
        case outcome = "outcome"
        case payload = "payload"
        case shortID = "shortId"
        case summary = "summary"
        case taskID = "taskId"
        case toolCallID = "toolCallId"
    }

    public init(approvalID: String?, createdAt: String, externalRefs: [String: ExternalRef], id: String, kind: String, outcome: ReceiptOutcome, payload: [String: JSONAny]?, shortID: String?, summary: String, taskID: String?, toolCallID: String?) {
        self.approvalID = approvalID
        self.createdAt = createdAt
        self.externalRefs = externalRefs
        self.id = id
        self.kind = kind
        self.outcome = outcome
        self.payload = payload
        self.shortID = shortID
        self.summary = summary
        self.taskID = taskID
        self.toolCallID = toolCallID
    }
}

public enum ExternalRef: Codable, Sendable {
    case double(Double)
    case string(String)

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Double.self) {
            self = .double(x)
            return
        }
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        throw DecodingError.typeMismatch(ExternalRef.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for ExternalRef"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .double(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        }
